<template>
  <section class="framework-page" aria-label="成员结算台账">
    <PageHeader title="成员结算台账" description="收款不等于分配。先确认每单可分配金额，再按产品与结算期预览，人工确认后形成成员收入。" />
    <p class="notice">此页面不发起银行转账；“已付”只登记线下付款凭据。代理佣金及历史分润在各自账本独立保留。</p>
    <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="message" role="status" class="notice">{{ message }}</p>
    <section class="panel"><h2>成员与余额</h2><form @submit.prevent="addMember"><div class="actions"><label>成员名称<input v-model="memberName" required maxlength="100"></label><button :disabled="busy || !memberName.trim()">新增成员</button><button type="button" :disabled="busy" @click="run(load)">刷新台账</button></div></form>
      <div class="table-wrap"><table><thead><tr><th>成员</th><th>应分</th><th>暂留</th><th>已付</th><th>未付</th><th>操作</th></tr></thead><tbody><tr v-for="member in summary.members" :key="member.id"><td>{{ member.name }}</td><td>{{ member.due }}</td><td>{{ member.held }}</td><td>{{ member.paid }}</td><td>{{ member.unpaid }}</td><td><button :disabled="busy" @click="selectPayment(member)">登记线下付款</button></td></tr></tbody></table></div>
      <p class="hint">总应分 ¥{{ summary.totals.due }} · 总暂留 ¥{{ summary.totals.held }} · 总已付 ¥{{ summary.totals.paid }}</p>
      <form v-if="payment.member_id" @submit.prevent="pay"><fieldset :disabled="busy" style="border:0;padding:0"><div class="fields"><label>本次实际付款金额<input v-model="payment.amount" inputmode="decimal" required placeholder="例如 100.00"></label><label>凭据编号<input v-model="payment.evidence" required></label><label>说明<input v-model="payment.note" required></label></div><div class="actions"><button class="primary">确认登记</button><button type="button" @click="payment.member_id = 0">取消</button></div></fieldset></form>
    </section>
    <section class="panel"><h2>私有分配策略</h2><p class="hint">导入你们确认的私有 JSON 配置，只存为草稿。不预填内部比例、不自动指定负责人。</p><label>选择策略配置<input type="file" accept=".json,application/json" :disabled="busy" @change="readPolicy"></label>
      <template v-if="policyDraft"><p>{{ policyDraft.name }} · 适用商品：{{ policyDraft.product_skus.join('、') }}</p><div class="table-wrap"><table><thead><tr><th>板块 / 子项</th><th>占总分配金额</th><th>分配方式</th></tr></thead><tbody><tr v-for="item in policyDraft.items" :key="item.code"><td>{{ item.group }} / {{ item.label }}</td><td>{{ displayRatio(item.ratio) }}%</td><td>{{ methodText(item.method) }}</td></tr></tbody></table></div><div class="actions"><button :disabled="busy" @click="importPolicy">导入为草稿</button></div></template>
      <div class="table-wrap"><table><thead><tr><th>策略</th><th>版本 / 状态</th><th>适用商品</th><th>操作</th></tr></thead><tbody><tr v-for="policy in policies" :key="policy.id"><td>{{ policy.name }}</td><td>{{ policy.version }} / {{ policy.status === 'draft' ? '草稿' : '已启用' }}</td><td>{{ policy.product_skus.join('、') }}</td><td><button v-if="policy.status === 'draft'" :disabled="busy" @click="activatePolicy(policy)">确认启用</button></td></tr></tbody></table></div>
    </section>
    <section class="panel"><h2>子项承担人</h2><form @submit.prevent="saveOwnership"><fieldset :disabled="busy" style="border:0;padding:0"><div class="fields"><label>策略<select v-model.number="ownership.policy_id" required><option :value="0" disabled>选择策略</option><option v-for="policy in policies" :key="policy.id" :value="policy.id">{{ policy.name }}</option></select></label><label>商品<select v-model="ownership.product_sku" required><option value="" disabled>选择商品</option><option v-for="sku in ownershipPolicy?.product_skus || []" :key="sku">{{ sku }}</option></select></label><label>子项<select v-model="ownership.item_code" required><option value="" disabled>选择子项</option><option v-for="item in ownershipPolicy?.items.filter(i => i.method === 'fixed') || []" :key="item.code" :value="item.code">{{ item.label }}</option></select></label><label>开始日期<input v-model="ownership.starts_on" type="date" required></label><label>结束日期（可空）<input v-model="ownership.ends_on" type="date"></label></div>
      <div v-for="(owner, index) in ownership.members" :key="index" class="actions"><label>承担人<select v-model.number="owner.member_id"><option :value="0" disabled>选择成员</option><option v-for="member in members.filter(m => m.active)" :key="member.id" :value="member.id">{{ member.name }}</option></select></label><label>子项内部权重（0–1）<input v-model="owner.weight" inputmode="decimal" required></label><button type="button" @click="ownership.members.splice(index, 1)">移除</button></div>
      <div class="actions"><button type="button" @click="ownership.members.push({ member_id: 0, weight: '' })">添加承担人</button><label class="check"><input v-model="ownership.disputed" type="checkbox">归属存在争议，暂留</label><button class="primary">保存归属</button><button type="button" @click="ownership.id = 0; ownership.expected_version = 0; ownership.members = []">新建</button></div><p class="hint">内部权重须合计为 1；无人认领、权重不完整或有争议的子项整体暂留。</p></fieldset></form>
      <div class="table-wrap"><table><thead><tr><th>商品 / 子项</th><th>生效期间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in ownerships" :key="row.id"><td>{{ row.product_sku }} / {{ row.item_code }}</td><td>{{ row.starts_on }} — {{ row.ends_on || '长期' }}</td><td>{{ row.disputed ? '争议暂留' : `${row.members.length} 名承担人` }}</td><td><button :disabled="busy" @click="editOwnership(row)">编辑</button></td></tr></tbody></table></div>
    </section>
    <section class="panel"><h2>每单本次分配金额</h2><form @submit.prevent="saveAllocation"><fieldset :disabled="busy" style="border:0;padding:0"><div class="fields"><label>新商品已收款订单<select v-model.number="allocation.order_id" required @change="selectAllocation"><option :value="0" disabled>选择订单</option><option v-for="order in orders.filter(o => o.status === 'paid')" :key="order.id" :value="order.id">#{{ order.id }} {{ order.commercial.definition.name }} · 实收 ¥{{ order.amount }}</option></select></label><label>本次分配金额（手工填写）<input v-model="allocation.amount" inputmode="decimal" required></label><label>结算期<input v-model="allocation.period" type="month" required></label><label>金额说明<input v-model="allocation.note" required></label><label>有效获客成员<select v-model.number="allocation.acquisition_member_id"><option :value="0">未归因（暂留）</option><option v-for="member in members.filter(m => m.active)" :key="member.id" :value="member.id">{{ member.name }}</option></select></label><label>咨询成交成员<select v-model.number="allocation.closing_member_id"><option :value="0">未归因（暂留）</option><option v-for="member in members.filter(m => m.active)" :key="member.id" :value="member.id">{{ member.name }}</option></select></label></div><div class="actions"><label class="check"><input v-model="allocation.is_repeat_purchase" type="checkbox">复购（不再计新获客）</label><button class="primary" :disabled="!allocation.order_id">保存分配金额</button></div></fieldset></form><p class="hint">不会自动把实收填入此处。金额不得超过净实收；已结算订单只能追加调账。</p></section>
    <section class="panel"><h2>按产品和结算期预览</h2><form @submit.prevent="makePreview"><div class="fields"><label>已启用策略<select v-model.number="previewForm.policy_id" required><option :value="0" disabled>选择策略</option><option v-for="policy in policies.filter(p => p.status === 'active')" :key="policy.id" :value="policy.id">{{ policy.name }}</option></select></label><label>商品<select v-model="previewForm.product_sku" required><option value="" disabled>选择商品</option><option v-for="sku in previewPolicy?.product_skus || []" :key="sku">{{ sku }}</option></select></label><label>结算期<input v-model="previewForm.period" type="month" required></label></div><div class="actions"><button :disabled="busy">生成分配预览</button></div></form>
      <template v-if="preview"><p class="notice">本次分配总额 ¥{{ preview.total_amount }}。确认前会再次检查金额、归属及履约版本。</p><div class="table-wrap"><table><thead><tr><th>订单 / 子项</th><th>成员</th><th>金额</th><th>状态 / 原因</th></tr></thead><tbody><tr v-for="(line, index) in preview.lines_snapshot" :key="index"><td>#{{ line.order_id }} {{ line.label }}</td><td>{{ memberLabel(line.member_id) }}</td><td>{{ line.amount }}</td><td>{{ bucketText(line.bucket) }} {{ line.held_reasons.map(reasonText).join('、') }}</td></tr></tbody></table></div><div class="actions"><button class="primary" :disabled="busy || preview.status !== 'preview'" @click="confirmPreview">确认进入成员台账</button></div></template>
    </section>
    <TeamLedgerAdjustments :orders="orders" :members="members" :service-codes="serviceCodes" @changed="run(load)" />
    <section class="panel"><h2>不可变明细</h2><div class="table-wrap"><table><thead><tr><th>编号 / 订单</th><th>成员 / 子项</th><th>类型</th><th>金额</th><th>说明</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.id"><td>#{{ entry.id }} / {{ entry.order_id || '—' }}</td><td>{{ memberLabel(entry.member_id) }} / {{ entry.item_code || '—' }}</td><td>{{ bucketText(entry.bucket) }} / {{ entry.kind }}</td><td>{{ entry.amount }}</td><td>{{ entry.note }}</td></tr></tbody></table></div><p v-if="!entries.length" class="empty">暂无正式台账明细。预览不会记入收入。</p></section>
  </section>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import PageHeader from '@/components/PageHeader.vue'
import { z } from 'zod'
import { api } from '@/utils/api'
import { confirmAction } from '@/shared/ui/confirm'
import { commercialApi, type CommercialOrder, type Envelope } from '@/features/admin/commercial'
import { useFrameworkTask } from '@/features/admin/useFrameworkTask'
import TeamLedgerAdjustments from '@/features/admin/TeamLedgerAdjustments.vue'
import '@/features/admin/framework.css'
const itemSchema = z.object({ code: z.string(), label: z.string(), group: z.string(), ratio: z.string(), method: z.enum(['fixed', 'acquisition', 'closing']).default('fixed'), service_code: z.string().nullable().optional() }).strict()
const policySchema = z.object({ name: z.string(), product_skus: z.array(z.string()), items: z.array(itemSchema) }).strict()
type PolicyDraft = z.infer<typeof policySchema>
type Policy = PolicyDraft & { id: number; version: number; status: string }
interface Member { id: number; name: string; active: boolean; version: number; ledger_version: number }
interface Balances { due: string; held: string; paid: string; unpaid: string }
interface Ownership { id: number; version: number; policy_id: number; product_sku: string; item_code: string; starts_on: string; ends_on: string | null; members: Array<{ member_id: number; weight: string }>; disputed: boolean }
interface Allocation { order_id: number; version: number; amount: string; period: string; note: string; acquisition_member_id: number | null; closing_member_id: number | null; is_repeat_purchase: boolean }
interface Preview { id: number; version: number; status: string; fingerprint: string; total_amount: string; lines_snapshot: Array<{ order_id: number; member_id: number | null; label: string; amount: string; bucket: string; held_reasons: string[] }> }
interface Entry { id: number; order_id: number | null; member_id: number | null; item_code: string | null; bucket: string; kind: string; amount: string; note: string }
const { busy, error, message, run } = useFrameworkTask()
const policies = ref<Policy[]>([]), policyDraft = ref<PolicyDraft | null>(null), members = ref<Member[]>([]), memberName = ref('')
const orders = ref<CommercialOrder[]>([]), allocations = ref<Allocation[]>([]), ownerships = ref<Ownership[]>([]), entries = ref<Entry[]>([])
const summary = ref<{ totals: Balances; members: Array<Member & Balances> }>({ totals: { due: '0.00', held: '0.00', paid: '0.00', unpaid: '0.00' }, members: [] })
const ownership = reactive({ id: 0, expected_version: 0, policy_id: 0, product_sku: '', item_code: '', starts_on: '', ends_on: '', members: [] as Array<{ member_id: number; weight: string }>, disputed: false })
const ownershipPolicy = computed(() => policies.value.find(p => p.id === ownership.policy_id))
const allocation = reactive({ order_id: 0, expected_version: 0, amount: '', period: '', note: '', acquisition_member_id: 0, closing_member_id: 0, is_repeat_purchase: false })
const previewForm = reactive({ policy_id: 0, product_sku: '', period: '' })
const previewPolicy = computed(() => policies.value.find(p => p.id === previewForm.policy_id))
const serviceCodes = computed(() => [...new Map(policies.value.flatMap(p => p.items.filter(i => i.service_code).map(i => [i.service_code!, { code: i.service_code!, label: i.label }] as const))).values()])
const preview = ref<Preview | null>(null)
const payment = reactive({ member_id: 0, amount: '', evidence: '', note: '', expected_ledger_version: 0, idempotency_key: '' })
const read = <T,>(path: string) => api.get<T>(`/api/team-ledger/${path}`, {}, { cache: false })
const memberLabel = (id: number | null) => members.value.find(m => m.id === id)?.name || '未分配'
const displayRatio = (ratio: string) => (Number(ratio) * 100).toFixed(2).replace(/\.00$/, '')
const methodText = (method: string) => ({ fixed: '按子项承担人', acquisition: '有效获客净实收', closing: '咨询成交净实收' }[method] || method)
const bucketText = (bucket: string) => ({ due: '应分', held: '暂留', paid: '已付' }[bucket] || bucket)
const reasonText = (reason: string) => ({ unassigned: '无人认领', disputed: '归属争议', service_unfulfilled: '服务未完成', incomplete_ownership: '权重未完整', inactive_member: '成员停用', missing_attribution: '缺少归因' }[reason] || reason)
async function load() { [policies.value, members.value, ownerships.value, allocations.value, entries.value, summary.value, orders.value] = await Promise.all([read<Policy[]>('policies'), read<Member[]>('members'), read<Ownership[]>('ownerships'), read<Allocation[]>('allocations'), read<Entry[]>('entries'), read<typeof summary.value>('summary'), commercialApi.orders()]) }
async function addMember() { await run(async () => { await api.post('/api/team-ledger/members', { name: memberName.value }); memberName.value = ''; await load() }) }
async function readPolicy(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; await run(async () => { policyDraft.value = null; if (file.size > 256000) throw new Error('配置文件不能超过 256 KB'); policyDraft.value = policySchema.parse(JSON.parse(await file.text())) }) }
async function importPolicy() { await run(async () => { if (!policyDraft.value) return; await api.post('/api/team-ledger/policies', policyDraft.value); policyDraft.value = null; await load() }, '策略已保存为草稿，尚未启用') }
async function activatePolicy(policy: Policy) { await run(async () => { if (!await confirmAction({ title: '确认启用分配策略', message: `${policy.name} 将用于人工选择的后续结算，不回算旧账。确认启用？` })) return; await api.post(`/api/team-ledger/policies/${policy.id}/activate`, { expected_version: policy.version }); await load() }) }
function editOwnership(row: Ownership) { Object.assign(ownership, row, { expected_version: row.version, ends_on: row.ends_on || '', members: row.members.map(m => ({ ...m })) }) }
async function saveOwnership() { await run(async () => { const body = { policy_id: ownership.policy_id, item_code: ownership.item_code, product_sku: ownership.product_sku, starts_on: ownership.starts_on, ends_on: ownership.ends_on || null, members: ownership.members, disputed: ownership.disputed }; if (ownership.id) await api.put(`/api/team-ledger/ownerships/${ownership.id}`, { ...body, expected_version: ownership.expected_version }); else await api.post('/api/team-ledger/ownerships', body); await load(); ownership.id = 0; ownership.expected_version = 0; ownership.members = [] }, '承担人配置已保存') }
function selectAllocation() { const row = allocations.value.find(a => a.order_id === allocation.order_id); Object.assign(allocation, { expected_version: row?.version || 0, amount: row?.amount || '', period: row?.period || '', note: row?.note || '', acquisition_member_id: row?.acquisition_member_id || 0, closing_member_id: row?.closing_member_id || 0, is_repeat_purchase: row?.is_repeat_purchase || false }) }
async function saveAllocation() { await run(async () => { const { order_id, ...body } = allocation; await api.put(`/api/team-ledger/orders/${order_id}/allocation`, { ...body, acquisition_member_id: body.acquisition_member_id || null, closing_member_id: body.closing_member_id || null }); await load(); selectAllocation(); preview.value = null }, '分配金额已保存，尚未记入成员收入') }
async function makePreview() { await run(async () => { const result = await api.post<Envelope<Preview>>('/api/team-ledger/settlements/preview', { ...previewForm }); preview.value = result.data }) }
async function confirmPreview() { await run(async () => { const current = preview.value; if (!current || !await confirmAction({ title: '确认结算', message: `总额 ¥${current.total_amount}，包含明确标示的暂留项。确认后生成不可覆盖的成员明细。` })) return; const result = await api.post<Envelope<Preview>>(`/api/team-ledger/settlements/${current.id}/confirm`, { expected_version: current.version, fingerprint: current.fingerprint }); preview.value = result.data; await load() }) }
function selectPayment(member: Member) { Object.assign(payment, { member_id: member.id, expected_ledger_version: member.ledger_version, amount: '', note: '', evidence: '', idempotency_key: crypto.randomUUID() }) }
async function pay() { await run(async () => { const body = { ...payment }; if (!await confirmAction({ title: '登记已发生的线下付款', message: `向 ${memberLabel(body.member_id)} 实际支付 ¥${body.amount}。此操作只记账，不发起转账。` })) return; await api.post('/api/team-ledger/payments', body); payment.member_id = 0; await load() }) }
onMounted(() => run(load))
</script>
